package com.nook.controller; import com.nook.dto.ApiDtos.*; import com.nook.security.CurrentUser; import com.nook.service.UserService; import jakarta.validation.Valid; import org.springframework.core.io.Resource; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.multipart.MultipartFile; import java.util.*; @RestController @RequestMapping("/api/v1") public class UserController {final UserService s;public UserController(UserService s){this.s=s;}@GetMapping("/users/me") Me me(){return s.me(CurrentUser.id());}@GetMapping("/users/me/settings") UserSettingsDto settings(){return s.settings(CurrentUser.id());}@PutMapping("/users/me/settings") UserSettingsDto updateSettings(@Valid @RequestBody UpdateUserSettings x){return s.updateSettings(CurrentUser.id(),x);}@PutMapping("/users/me/location") @ResponseStatus(HttpStatus.NO_CONTENT) void updateLocation(@Valid @RequestBody UpdateUserLocation x){s.updateLocation(CurrentUser.id(),x);}@GetMapping("/users/{id}") DiscoverProfile profile(@PathVariable UUID id){return s.profile(CurrentUser.id(),id);}@PatchMapping("/users/me") Me update(@Valid @RequestBody UpdateMe x){return s.update(CurrentUser.id(),x);}@PostMapping(value="/users/me/photos",consumes=MediaType.APPLICATION_JSON_VALUE) @ResponseStatus(HttpStatus.CREATED) PhotoDto photo(@Valid @RequestBody PhotoRequest x){return s.photo(CurrentUser.id(),x);}@PostMapping(value="/users/me/photos",consumes=MediaType.MULTIPART_FORM_DATA_VALUE) @ResponseStatus(HttpStatus.CREATED) PhotoDto photoUpload(@RequestPart("file") MultipartFile file){return s.uploadPhoto(CurrentUser.id(),file);}@PatchMapping("/users/me/photos/reorder") List<PhotoDto> reorder(@Valid @RequestBody PhotoOrder x){return s.reorderPhotos(CurrentUser.id(),x.photoIds());}@PatchMapping("/users/me/photos/{id}/primary") PhotoDto primary(@PathVariable UUID id){return s.makePrimary(CurrentUser.id(),id);}@GetMapping("/media/photos/{filename:.+}") ResponseEntity<Resource> photoFile(@PathVariable String filename){return ResponseEntity.ok().header(HttpHeaders.CACHE_CONTROL,"public, max-age=86400").body(s.photoResource(filename));}@DeleteMapping("/users/me/photos/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void photoDelete(@PathVariable UUID id){s.removePhoto(CurrentUser.id(),id);}@PostMapping("/users/{id}/block") @ResponseStatus(HttpStatus.NO_CONTENT) void block(@PathVariable UUID id){s.block(CurrentUser.id(),id);}@PostMapping("/users/{id}/report") @ResponseStatus(HttpStatus.NO_CONTENT) void report(@PathVariable UUID id,@Valid @RequestBody ReportRequest x){s.report(CurrentUser.id(),id,x);}@DeleteMapping("/users/me") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(){s.deleteAccount(CurrentUser.id());}}
